/**
 * De PSV Campaign Kit, v1.0. Gegenereerd met `scripts/kit-bijwerken.mjs`
 * uit de skill playable-page-builder; niet met de hand aanpassen.
 */

export const KIT_VERSIE = "v1.0";

/** `assets/psv-framework.css`: hoort ongewijzigd in elke pagina. */
export const FRAMEWORK_CSS = "/* ============================================================\n   PSV CAMPAIGN KIT — v1.0\n   Basis-CSS voor campagnepagina's in Playable.\n\n   Plak dit ONGEWIJZIGD bovenaan het CSS-veld.\n   Pagina-specifieke CSS zet je eronder, met een eigen prefix.\n\n   Alles staat achter #psvk-app, dus niets lekt naar Playable.\n   Prefix: psvk-  |  Root-id: psvk-app\n   ============================================================ */\n\n\n/* ============================================================\n   1. TOKENS\n   Pas hier aan per campagne, niet verderop in het bestand.\n   ============================================================ */\n\n#psvk-app {\n  /* --- Kleur --- */\n  --psvk-red: #EE2523;\n  --psvk-red-dark: #C41A18;\n  --psvk-black: #0D0D0D;\n  --psvk-ink: #1A1A1A;\n  --psvk-grey: #F4F4F4;\n  --psvk-grey-mid: #6B6B6B;\n  --psvk-white: #FFFFFF;\n\n  --psvk-hair: rgba(0, 0, 0, 0.10);          /* lijn op licht */\n  --psvk-hair-light: rgba(255, 255, 255, 0.16); /* lijn op donker */\n  --psvk-veil: rgba(0, 0, 0, 0.40);          /* vlak op donkere foto */\n\n  /* --- Achtergrondafbeeldingen per sectiekleur --- */\n  --psvk-bg-red: url('https://psv-eindhoven.campaign.playable.com/files/4075/uploads/81295b51-ab53-4961-a4fb-a26a77423e16.jpg');\n  --psvk-bg-light: url('https://psv-eindhoven.campaign.playable.com/files/4075/uploads/064f0a5e-ebab-44e6-aa1f-e4d310e390fe.jpg');\n  --psvk-bg-dark: url('https://psv-eindhoven.campaign.playable.com/files/4075/uploads/9416b73b-8608-4074-b678-06a37a2c7a52.jpg');\n  /* hoeveel wit er over de lichte achtergrond ligt: 0.75 = beeld op 25% */\n  --psvk-bg-light-veil: 0.75;\n\n  /* --- Typografie --- */\n  --psvk-display: 'PSV Condensed', 'Arial Narrow', sans-serif;\n  --psvk-body: 'PSV Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Arial, sans-serif;\n\n  --psvk-size-hero: clamp(60px, 13vw, 148px);\n  --psvk-size-title: clamp(34px, 5.2vw, 60px);\n  --psvk-size-sub: clamp(26px, 3.4vw, 38px);\n  --psvk-size-lead: 17px;\n  --psvk-size-body: 16px;\n  --psvk-size-small: 14px;\n  --psvk-size-meta: 12.5px;\n\n  /* --- Ritme --- */\n  --psvk-max: 1240px;         /* contentbreedte */\n  --psvk-gutter: 24px;        /* marge links en rechts */\n  --psvk-section: 78px;       /* verticale ruimte per sectie */\n  --psvk-section-sm: 58px;    /* idem op mobiel */\n  --psvk-head-gap: 44px;      /* onder een sectiekop */\n  --psvk-gap: 18px;           /* tussen kaarten */\n\n  /* --- Vorm --- */\n  --psvk-radius: 0;           /* PSV is hoekig; zet hier 4px voor zachter */\n  --psvk-rule: 3px;           /* dikte van een rood accentlijntje */\n\n  /* --- Basis --- */\n  font-family: var(--psvk-body);\n  font-size: var(--psvk-size-body);\n  line-height: 1.55;\n  color: var(--psvk-ink);\n  background: var(--psvk-white);\n  -webkit-font-smoothing: antialiased;\n}\n\n\n/* ============================================================\n   2. RESET BINNEN SCOPE\n   De !important-regels op lijsten zijn nodig: Playable zet\n   list-style en padding op li-niveau terug.\n   ============================================================ */\n\n#psvk-app *,\n#psvk-app *::before,\n#psvk-app *::after { box-sizing: border-box; margin: 0; padding: 0; }\n\n#psvk-app a { color: inherit; text-decoration: none; }\n#psvk-app ul, #psvk-app ol { list-style: none !important; padding-left: 0 !important; }\n#psvk-app li { list-style: none !important; list-style-type: none !important; }\n#psvk-app li::marker { content: '' !important; font-size: 0 !important; }\n#psvk-app li::before { content: none !important; }\n#psvk-app img, #psvk-app svg { display: block; max-width: 100%; }\n#psvk-app button,\n#psvk-app input,\n#psvk-app select,\n#psvk-app textarea { font: inherit; color: inherit; }\n#psvk-app button { background: none; border: none; cursor: pointer; }\n#psvk-app :focus-visible { outline: 3px solid var(--psvk-red); outline-offset: 3px; }\n\n/* Let op: een <ul> die zelf de gutter draagt, verliest die door de\n   reset hierboven. Gebruik dan .psvk-list-wrap of zet de padding\n   met !important terug. */\n\n\n/* ============================================================\n   3. LAYOUT\n   ============================================================ */\n\n#psvk-app .psvk-wrap {\n  max-width: var(--psvk-max);\n  margin: 0 auto;\n  padding: 0 var(--psvk-gutter);\n}\n#psvk-app .psvk-wrap-narrow { max-width: 820px; }\n\n/* Elke sectie is een .psvk-section met één kleurvariant */\n#psvk-app .psvk-section { padding: var(--psvk-section) 0; }\n#psvk-app .psvk-section-tight { padding: calc(var(--psvk-section) * 0.6) 0; }\n#psvk-app .psvk-section-flush { padding: 0; }\n\n#psvk-app .psvk-light,\n#psvk-app .psvk-grey {\n  background-color: var(--psvk-white);\n  background-image:\n    linear-gradient(\n      rgba(255, 255, 255, var(--psvk-bg-light-veil)),\n      rgba(255, 255, 255, var(--psvk-bg-light-veil))\n    ),\n    var(--psvk-bg-light);\n  background-size: cover; background-position: center; background-repeat: no-repeat;\n}\n#psvk-app .psvk-grey { background-color: var(--psvk-grey); }\n\n#psvk-app .psvk-dark {\n  background-color: var(--psvk-black);\n  background-image: var(--psvk-bg-dark);\n  background-size: cover; background-position: center; background-repeat: no-repeat;\n  color: var(--psvk-white);\n}\n\n#psvk-app .psvk-red {\n  background-color: var(--psvk-red);\n  background-image: var(--psvk-bg-red);\n  background-size: cover; background-position: center; background-repeat: no-repeat;\n  color: var(--psvk-white);\n}\n\n#psvk-app .psvk-plain { background: var(--psvk-white); background-image: none; }\n#psvk-app .psvk-plain-dark { background: var(--psvk-black); background-image: none; color: var(--psvk-white); }\n\n/* Tekst op donkere en rode secties */\n#psvk-app .psvk-dark .psvk-lead,\n#psvk-app .psvk-red .psvk-lead,\n#psvk-app .psvk-plain-dark .psvk-lead { color: rgba(255, 255, 255, 0.72); }\n\n/* Kolommen. Zakken vanzelf terug op smallere schermen. */\n#psvk-app .psvk-grid { display: grid; gap: var(--psvk-gap); }\n#psvk-app .psvk-grid-2 { grid-template-columns: repeat(2, 1fr); }\n#psvk-app .psvk-grid-3 { grid-template-columns: repeat(3, 1fr); }\n#psvk-app .psvk-grid-4 { grid-template-columns: repeat(4, 1fr); }\n#psvk-app .psvk-grid-auto { grid-template-columns: repeat(auto-fill, minmax(240px, 1fr)); }\n\n#psvk-app .psvk-split {\n  display: grid; grid-template-columns: 1fr 1fr;\n  gap: 48px; align-items: center;\n}\n#psvk-app .psvk-split-wide { grid-template-columns: 1.4fr 1fr; }\n\n\n/* ============================================================\n   4. TYPOGRAFIE\n   ============================================================ */\n\n#psvk-app .psvk-hero-title,\n#psvk-app .psvk-title,\n#psvk-app .psvk-subtitle {\n  font-family: var(--psvk-display);\n  text-transform: uppercase;\n  letter-spacing: 0.005em;\n}\n\n#psvk-app .psvk-hero-title {\n  font-size: var(--psvk-size-hero);\n  line-height: 0.84;\n  margin-bottom: 24px;\n}\n#psvk-app .psvk-title {\n  font-size: var(--psvk-size-title);\n  line-height: 0.94;\n  margin-bottom: 14px;\n}\n#psvk-app .psvk-subtitle {\n  font-size: var(--psvk-size-sub);\n  line-height: 1;\n  margin-bottom: 10px;\n}\n\n/* Wit blok achter een woord in een titel, de PSV-manier om te accentueren */\n#psvk-app .psvk-mark {\n  display: inline-block;\n  background: var(--psvk-white); color: var(--psvk-red);\n  padding: 0 18px 6px;\n}\n#psvk-app .psvk-mark-red { background: var(--psvk-red); color: var(--psvk-white); }\n\n#psvk-app .psvk-lead {\n  max-width: 620px;\n  font-size: var(--psvk-size-lead);\n  color: var(--psvk-grey-mid);\n}\n#psvk-app .psvk-prose { max-width: 66ch; }\n#psvk-app .psvk-prose p + p { margin-top: 1em; }\n\n#psvk-app .psvk-meta {\n  font-size: var(--psvk-size-meta);\n  letter-spacing: 0.05em;\n  color: var(--psvk-grey-mid);\n}\n#psvk-app .psvk-dark .psvk-meta,\n#psvk-app .psvk-red .psvk-meta { color: rgba(255, 255, 255, 0.7); }\n\n/* Kop van een sectie: titel plus optionele lead */\n#psvk-app .psvk-head { margin-bottom: var(--psvk-head-gap); }\n\n\n/* ============================================================\n   5. HEADER\n   ============================================================ */\n\n#psvk-app .psvk-header {\n  position: sticky; top: 0; z-index: 100;\n  background-color: var(--psvk-red);\n  background-image: none;\n}\n#psvk-app .psvk-header-inner {\n  display: flex; align-items: center; justify-content: center;\n  padding-top: 14px; padding-bottom: 14px;\n}\n#psvk-app .psvk-logo { display: block; }\n#psvk-app .psvk-logo img { height: 54px; width: auto; }\n\n\n/* ============================================================\n   6. HERO\n   Donkere gradient bovenin houdt witte tekst leesbaar op beeld.\n   ============================================================ */\n\n#psvk-app .psvk-hero { position: relative; }\n#psvk-app .psvk-hero::before {\n  content: '';\n  position: absolute; inset: 0; z-index: 1;\n  background: linear-gradient(\n    to bottom,\n    rgba(0, 0, 0, 0.60) 0%,\n    rgba(0, 0, 0, 0.35) 40%,\n    rgba(0, 0, 0, 0) 80%\n  );\n  pointer-events: none;\n}\n#psvk-app .psvk-hero-inner {\n  position: relative; z-index: 2;\n  max-width: var(--psvk-max); margin: 0 auto;\n  padding: 96px var(--psvk-gutter) 76px;\n}\n#psvk-app .psvk-hero-lead {\n  max-width: 560px; font-size: 18px;\n  color: rgba(255, 255, 255, 0.94);\n  margin-bottom: 34px;\n}\n#psvk-app .psvk-hero-cta { display: flex; flex-wrap: wrap; gap: 14px; }\n\n\n/* ============================================================\n   7. CIJFERBALK\n   Hoort onderaan een hero. Gebruik data-psvk-count voor de teller.\n   ============================================================ */\n\n#psvk-app .psvk-stats {\n  position: relative; z-index: 2;\n  max-width: var(--psvk-max); margin: 0 auto;\n  padding: 0 var(--psvk-gutter) !important; /* wint van de ul-reset */\n  display: grid; grid-template-columns: repeat(3, 1fr);\n  border-top: 1px solid rgba(255, 255, 255, 0.28);\n}\n#psvk-app .psvk-stats-4 { grid-template-columns: repeat(4, 1fr); }\n#psvk-app .psvk-stats li {\n  padding: 24px 20px 30px 0;\n  display: flex; flex-direction: column; gap: 2px;\n  min-width: 0;\n}\n#psvk-app .psvk-stat-num {\n  font-family: var(--psvk-display);\n  font-size: 46px; line-height: 1;\n}\n#psvk-app .psvk-stat-label {\n  font-size: 13px; letter-spacing: 0.1em; text-transform: uppercase;\n  color: rgba(255, 255, 255, 0.72);\n}\n\n\n/* ============================================================\n   8. KNOPPEN\n   ============================================================ */\n\n#psvk-app .psvk-btn {\n  display: inline-flex; align-items: center; gap: 10px;\n  padding: 15px 30px;\n  font-family: var(--psvk-display);\n  font-size: 17px; letter-spacing: 0.08em; text-transform: uppercase;\n  border: 2px solid transparent;\n  border-radius: var(--psvk-radius);\n  transition: background-color 0.18s ease, color 0.18s ease, border-color 0.18s ease;\n}\n#psvk-app .psvk-btn::after {\n  content: ''; width: 8px; height: 8px;\n  border-top: 2px solid currentColor; border-right: 2px solid currentColor;\n  transform: rotate(45deg);\n}\n#psvk-app .psvk-btn-flat::after { display: none; }\n\n#psvk-app .psvk-btn-primary { background: var(--psvk-red); color: var(--psvk-white); }\n#psvk-app .psvk-btn-primary:hover { background: var(--psvk-white); color: var(--psvk-red); }\n\n#psvk-app .psvk-btn-light { background: var(--psvk-white); color: var(--psvk-red); border-color: var(--psvk-white); }\n#psvk-app .psvk-btn-light:hover { background: var(--psvk-black); color: var(--psvk-white); border-color: var(--psvk-black); }\n\n#psvk-app .psvk-btn-outline { border-color: var(--psvk-white); color: var(--psvk-white); }\n#psvk-app .psvk-btn-outline:hover { background: var(--psvk-white); color: var(--psvk-red); }\n\n#psvk-app .psvk-btn-dark { background: var(--psvk-black); color: var(--psvk-white); }\n#psvk-app .psvk-btn-dark:hover { background: var(--psvk-red); color: var(--psvk-white); }\n\n/* Op een rode achtergrond wisselt de hoofdknop automatisch naar wit */\n#psvk-app .psvk-red .psvk-btn-primary,\n#psvk-app .psvk-hero .psvk-btn-primary {\n  background: var(--psvk-white); color: var(--psvk-red); border-color: var(--psvk-white);\n}\n#psvk-app .psvk-red .psvk-btn-primary:hover,\n#psvk-app .psvk-hero .psvk-btn-primary:hover {\n  background: var(--psvk-black); color: var(--psvk-white); border-color: var(--psvk-black);\n}\n\n/* Tekstlink met pijl. Font staat vast omdat Playable links opblaast. */\n#psvk-app a.psvk-link {\n  display: inline-flex; align-items: center; gap: 8px;\n  font-family: var(--psvk-body) !important;\n  font-size: 11.5px !important;\n  font-weight: 600 !important;\n  line-height: 1.4 !important;\n  letter-spacing: 0.09em; text-transform: uppercase;\n  color: var(--psvk-ink);\n  text-decoration: none !important;\n  transition: color 0.16s ease;\n}\n#psvk-app a.psvk-link::after {\n  content: ''; flex: none; width: 7px; height: 7px;\n  border-top: 2px solid var(--psvk-red); border-right: 2px solid var(--psvk-red);\n  transform: rotate(45deg);\n  transition: transform 0.16s ease;\n}\n#psvk-app a.psvk-link:hover { color: var(--psvk-red); }\n#psvk-app a.psvk-link:hover::after { transform: rotate(45deg) translate(2px, -2px); }\n#psvk-app .psvk-dark a.psvk-link { color: var(--psvk-white); }\n\n/* Variant die onderaan een kaart plakt, met rode scheidingslijn */\n#psvk-app a.psvk-link-footer {\n  width: 100%; justify-content: space-between;\n  margin-top: auto; padding-top: 12px;\n  border-top: var(--psvk-rule) solid var(--psvk-red);\n}\n\n\n/* ============================================================\n   9. KAARTEN\n   ============================================================ */\n\n#psvk-app .psvk-card {\n  display: block;\n  background: var(--psvk-white);\n  border: 1px solid var(--psvk-hair);\n  border-radius: var(--psvk-radius);\n  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n}\n#psvk-app .psvk-card-hover:hover { transform: translateY(-3px); box-shadow: 0 14px 30px rgba(0, 0, 0, 0.12); }\n#psvk-app .psvk-card[hidden] { display: none; }\n\n#psvk-app .psvk-card-media {\n  position: relative;\n  aspect-ratio: 4 / 5;\n  background: linear-gradient(168deg, var(--psvk-red) 0%, var(--psvk-red-dark) 70%, var(--psvk-black) 100%);\n  overflow: hidden;\n}\n#psvk-app .psvk-card-media-square { aspect-ratio: 1 / 1; }\n#psvk-app .psvk-card-media-wide { aspect-ratio: 16 / 9; }\n#psvk-app .psvk-card-media img { width: 100%; height: 100%; object-fit: cover; object-position: center top; }\n\n#psvk-app .psvk-card-body {\n  position: relative;\n  padding: 16px 18px 20px;\n  display: flex; flex-direction: column; flex: 1;\n}\n#psvk-app .psvk-card-title {\n  font-family: var(--psvk-display);\n  font-size: 25px; line-height: 0.98; text-transform: uppercase;\n}\n#psvk-app .psvk-card-text { font-size: var(--psvk-size-small); color: var(--psvk-grey-mid); margin-top: 8px; }\n#psvk-app .psvk-card-meta {\n  margin-top: 8px; padding-top: 8px;\n  border-top: 1px solid var(--psvk-hair);\n  font-size: var(--psvk-size-meta); letter-spacing: 0.05em; color: var(--psvk-grey-mid);\n}\n\n/* Labels op beeld */\n#psvk-app .psvk-badge {\n  position: absolute; top: 12px; left: 12px;\n  background: var(--psvk-white); color: var(--psvk-red);\n  font-size: 10.5px; letter-spacing: 0.1em; text-transform: uppercase;\n  padding: 5px 10px;\n}\n#psvk-app .psvk-strip {\n  position: absolute; left: 0; bottom: 0;\n  background: var(--psvk-black); color: var(--psvk-white);\n  font-size: 11.5px; letter-spacing: 0.1em; text-transform: uppercase;\n  padding: 6px 12px;\n}\n/* Groot cijfer dat over de onderrand van het beeld hangt */\n#psvk-app .psvk-overhang {\n  position: absolute; bottom: 100%; right: 14px; margin-bottom: 10px;\n  font-family: var(--psvk-display);\n  font-size: 46px; line-height: 1;\n  color: var(--psvk-white);\n  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.35);\n}\n\n/* Kort oplichten wanneer je ergens naartoe springt */\n#psvk-app .psvk-flash {\n  border-color: var(--psvk-red);\n  animation: psvkPulse 1.3s ease-out 2;\n}\n@keyframes psvkPulse {\n  0%   { box-shadow: 0 0 0 0 rgba(238, 37, 35, 0.75); }\n  70%  { box-shadow: 0 0 0 16px rgba(238, 37, 35, 0); }\n  100% { box-shadow: 0 0 0 0 rgba(238, 37, 35, 0); }\n}\n\n\n/* ============================================================\n   10. TEGELS\n   Vierkante blokjes op een donkere sectie: nummers, datums, iconen.\n   ============================================================ */\n\n#psvk-app .psvk-tiles {\n  display: grid; grid-template-columns: repeat(auto-fill, minmax(84px, 1fr)); gap: 10px;\n}\n#psvk-app .psvk-tile {\n  width: 100%; aspect-ratio: 1 / 1;\n  display: flex; align-items: center; justify-content: center;\n  font-family: var(--psvk-display);\n  font-size: 34px; line-height: 1;\n  color: var(--psvk-white);\n  background: var(--psvk-veil);\n  border: 1px solid var(--psvk-hair-light);\n  border-radius: var(--psvk-radius);\n  transition: background-color 0.16s ease, color 0.16s ease, transform 0.16s ease;\n}\n#psvk-app .psvk-tile:hover { background: var(--psvk-white); color: var(--psvk-black); transform: translateY(-2px); }\n#psvk-app .psvk-tile-accent { border-color: var(--psvk-red); background: rgba(238, 37, 35, 0.55); }\n#psvk-app .psvk-tile.psvk-tile-on { background: var(--psvk-red); color: var(--psvk-white); border-color: var(--psvk-red); }\n\n#psvk-app .psvk-legend {\n  display: flex; align-items: center; gap: 8px;\n  margin-top: 18px;\n  font-size: var(--psvk-size-meta); letter-spacing: 0.06em; text-transform: uppercase;\n  color: rgba(255, 255, 255, 0.6);\n}\n#psvk-app .psvk-legend-dot {\n  width: 13px; height: 13px; display: inline-block;\n  background: rgba(238, 37, 35, 0.55); border: 1px solid var(--psvk-red);\n}\n\n\n/* ============================================================\n   11. TOOLBAR: filters en zoeken\n   ============================================================ */\n\n#psvk-app .psvk-toolbar {\n  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between;\n  gap: 16px;\n  margin-bottom: 30px; padding-bottom: 22px;\n  border-bottom: 1px solid var(--psvk-hair);\n}\n#psvk-app .psvk-filters { display: flex; flex-wrap: wrap; gap: 8px; }\n#psvk-app .psvk-filter {\n  display: inline-flex; align-items: center; gap: 8px;\n  padding: 10px 18px;\n  font-family: var(--psvk-display);\n  font-size: 17px; letter-spacing: 0.06em; text-transform: uppercase;\n  border: 1px solid var(--psvk-hair);\n  border-radius: var(--psvk-radius);\n  background: var(--psvk-white);\n  color: var(--psvk-ink);\n  transition: background-color 0.16s ease, color 0.16s ease, border-color 0.16s ease;\n}\n#psvk-app .psvk-filter span {\n  font-family: var(--psvk-body); font-size: 11.5px;\n  color: var(--psvk-grey-mid); transition: color 0.16s ease;\n}\n#psvk-app .psvk-filter:hover { border-color: var(--psvk-ink); }\n#psvk-app .psvk-filter-accent { border-color: var(--psvk-red); color: var(--psvk-red); }\n#psvk-app .psvk-filter-accent span { color: var(--psvk-red); opacity: 0.7; }\n#psvk-app .psvk-filter.psvk-filter-on {\n  background: var(--psvk-red); color: var(--psvk-white); border-color: var(--psvk-red);\n}\n#psvk-app .psvk-filter.psvk-filter-on span { color: rgba(255, 255, 255, 0.75); }\n\n#psvk-app .psvk-search { position: relative; flex: 0 1 260px; min-width: 200px; }\n#psvk-app .psvk-search input {\n  width: 100%;\n  padding: 11px 40px 11px 14px;\n  font-family: var(--psvk-body); font-size: 14.5px;\n  color: var(--psvk-ink); background: var(--psvk-white);\n  border: 1px solid var(--psvk-hair);\n  border-radius: var(--psvk-radius);\n  -webkit-appearance: none; appearance: none;\n  transition: border-color 0.16s ease;\n}\n#psvk-app .psvk-search input::placeholder { color: var(--psvk-grey-mid); }\n#psvk-app .psvk-search input:focus { border-color: var(--psvk-red); outline: none; }\n#psvk-app .psvk-search-clear {\n  position: absolute; top: 50%; right: 6px; transform: translateY(-50%);\n  width: 28px; height: 28px;\n  display: flex; align-items: center; justify-content: center;\n  font-size: 22px; line-height: 1; color: var(--psvk-grey-mid);\n  transition: color 0.16s ease;\n}\n#psvk-app .psvk-search-clear:hover { color: var(--psvk-red); }\n#psvk-app .psvk-search-clear[hidden] { display: none; }\n\n#psvk-app .psvk-empty { margin-top: 24px; color: var(--psvk-grey-mid); }\n\n\n/* ============================================================\n   12. RIJENLIJST\n   Label links, waarde rechts. Voor staf, feiten, programma, prijzen.\n   ============================================================ */\n\n#psvk-app .psvk-rows { display: grid; grid-template-columns: repeat(2, 1fr); gap: 0 44px; }\n#psvk-app .psvk-rows-single { grid-template-columns: 1fr; }\n#psvk-app .psvk-rows li {\n  display: flex; justify-content: space-between; align-items: baseline; gap: 20px;\n  padding: 15px 0;\n  border-bottom: 1px solid var(--psvk-hair);\n}\n#psvk-app .psvk-dark .psvk-rows li { border-bottom-color: var(--psvk-hair-light); }\n#psvk-app .psvk-row-label {\n  font-size: var(--psvk-size-meta); letter-spacing: 0.09em; text-transform: uppercase;\n  color: var(--psvk-grey-mid);\n}\n#psvk-app .psvk-row-value {\n  font-family: var(--psvk-display);\n  font-size: 23px; text-transform: uppercase; text-align: right;\n}\n\n\n/* ============================================================\n   13. UITKLAPPER\n   Voor vragen en antwoorden of lange toelichtingen.\n   ============================================================ */\n\n#psvk-app .psvk-accordion { border-top: 1px solid var(--psvk-hair); }\n#psvk-app .psvk-accordion-item { border-bottom: 1px solid var(--psvk-hair); }\n#psvk-app .psvk-accordion-head {\n  width: 100%;\n  display: flex; align-items: center; justify-content: space-between; gap: 20px;\n  padding: 18px 0; text-align: left;\n  font-family: var(--psvk-display);\n  font-size: 21px; text-transform: uppercase;\n}\n#psvk-app .psvk-accordion-icon {\n  flex: none; width: 10px; height: 10px;\n  border-right: 2px solid var(--psvk-red); border-bottom: 2px solid var(--psvk-red);\n  transform: rotate(45deg) translate(-2px, -2px);\n  transition: transform 0.2s ease;\n}\n#psvk-app .psvk-accordion-head[aria-expanded=\"true\"] .psvk-accordion-icon {\n  transform: rotate(-135deg) translate(-2px, -2px);\n}\n#psvk-app .psvk-accordion-body { padding: 0 0 20px; max-width: 66ch; color: var(--psvk-grey-mid); }\n#psvk-app .psvk-accordion-body[hidden] { display: none; }\n\n\n/* ============================================================\n   14. FOOTER\n   ============================================================ */\n\n#psvk-app .psvk-footer { background: var(--psvk-black); }\n#psvk-app .psvk-footer-note {\n  padding: 26px 0 30px;\n  text-align: center;\n  font-family: var(--psvk-display);\n  font-size: 20px; letter-spacing: 0.14em; text-transform: uppercase;\n  color: var(--psvk-white);\n}\n\n\n/* ============================================================\n   15. STICKY ACTIEBALK\n   ============================================================ */\n\n#psvk-app .psvk-promobar {\n  position: fixed; left: 0; right: 0; bottom: 0; z-index: 90;\n  background: var(--psvk-black);\n  border-top: var(--psvk-rule) solid var(--psvk-red);\n  transform: translateY(100%);\n  transition: transform 0.3s ease;\n}\n#psvk-app .psvk-promobar.psvk-promobar-in { transform: translateY(0); }\n\n#psvk-app .psvk-promobar-inner {\n  position: relative;\n  display: flex; align-items: center; gap: 20px;\n  padding-top: 14px; padding-bottom: 14px;\n}\n#psvk-app .psvk-promobar-copy { display: flex; align-items: center; gap: 14px; flex: 1; min-width: 0; }\n#psvk-app .psvk-promobar-badge {\n  flex: none;\n  display: inline-flex; align-items: center;\n  background: var(--psvk-red); color: var(--psvk-white);\n  font-family: var(--psvk-display);\n  font-size: 17px; line-height: 1; letter-spacing: 0.06em; text-transform: uppercase;\n  padding: 9px 12px 7px;\n}\n#psvk-app .psvk-promobar-text { font-size: 14.5px; color: rgba(255, 255, 255, 0.82); margin: 0; }\n#psvk-app .psvk-promobar-cta {\n  flex: none;\n  display: inline-flex; align-items: center; gap: 10px;\n  padding: 13px 26px;\n  background: var(--psvk-red); color: var(--psvk-white);\n  font-family: var(--psvk-display);\n  font-size: 17px; letter-spacing: 0.08em; text-transform: uppercase;\n  text-decoration: none;\n  transition: background-color 0.18s ease, color 0.18s ease;\n}\n#psvk-app .psvk-promobar-cta::after {\n  content: ''; width: 8px; height: 8px;\n  border-top: 2px solid currentColor; border-right: 2px solid currentColor;\n  transform: rotate(45deg);\n}\n#psvk-app .psvk-promobar-cta:hover { background: var(--psvk-white); color: var(--psvk-red); }\n#psvk-app .psvk-promobar-close {\n  flex: none;\n  width: 34px; height: 34px;\n  display: flex; align-items: center; justify-content: center;\n  font-size: 26px; line-height: 1;\n  color: rgba(255, 255, 255, 0.7);\n  border: 1px solid rgba(255, 255, 255, 0.25);\n  transition: color 0.16s ease, border-color 0.16s ease;\n}\n#psvk-app .psvk-promobar-close:hover { color: var(--psvk-white); border-color: var(--psvk-white); }\n\n#psvk-app.psvk-has-promobar .psvk-footer { padding-bottom: 84px; }\n\n\n/* ============================================================\n   16. HULPKLASSEN\n   ============================================================ */\n\n#psvk-app .psvk-visually-hidden {\n  position: absolute; width: 1px; height: 1px;\n  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap;\n}\n#psvk-app .psvk-skiplink {\n  position: absolute; left: -9999px; top: 0; z-index: 200;\n  background: var(--psvk-red); color: var(--psvk-white); padding: 10px 18px;\n}\n#psvk-app .psvk-skiplink:focus { left: 16px; top: 16px; }\n\n#psvk-app .psvk-rule { border: 0; border-top: var(--psvk-rule) solid var(--psvk-red); width: 64px; margin: 0 0 20px; }\n#psvk-app .psvk-center { text-align: center; }\n#psvk-app .psvk-center .psvk-lead { margin-left: auto; margin-right: auto; }\n#psvk-app .psvk-stack { display: flex; flex-wrap: wrap; gap: 14px; }\n#psvk-app .psvk-stack-tight { gap: 8px; }\n\n\n/* ============================================================\n   17. MOTION\n   ============================================================ */\n\n@media (prefers-reduced-motion: reduce) {\n  #psvk-app .psvk-card-hover:hover,\n  #psvk-app .psvk-tile:hover { transform: none; }\n  #psvk-app .psvk-promobar { transition: none; }\n  #psvk-app .psvk-flash { animation: none; box-shadow: 0 0 0 3px var(--psvk-red); }\n}\n\n\n/* ============================================================\n   18. RESPONSIVE\n   Breekpunten: 1080 / 820 / 720 / 520.\n   ============================================================ */\n\n@media (max-width: 1080px) {\n  #psvk-app .psvk-grid-4 { grid-template-columns: repeat(3, 1fr); }\n  #psvk-app .psvk-grid-3 { grid-template-columns: repeat(2, 1fr); }\n}\n\n@media (max-width: 820px) {\n  #psvk-app { --psvk-section: var(--psvk-section-sm); }\n  #psvk-app .psvk-hero-inner { padding: 68px var(--psvk-gutter) 56px; }\n  #psvk-app .psvk-grid-4,\n  #psvk-app .psvk-grid-3,\n  #psvk-app .psvk-grid-2 { grid-template-columns: repeat(2, 1fr); }\n  #psvk-app .psvk-split,\n  #psvk-app .psvk-split-wide { grid-template-columns: 1fr; gap: 32px; }\n  #psvk-app .psvk-rows { grid-template-columns: 1fr; }\n  #psvk-app .psvk-search { flex: 1 1 100%; }\n}\n\n@media (max-width: 720px) {\n  #psvk-app .psvk-promobar-inner {\n    flex-direction: column; align-items: stretch; gap: 14px;\n    padding-top: 16px; padding-bottom: 18px;\n  }\n  #psvk-app .psvk-promobar-close {\n    position: absolute; top: 14px; right: var(--psvk-gutter);\n    width: 30px; height: 30px; font-size: 22px;\n  }\n  #psvk-app .psvk-promobar-copy {\n    flex-direction: column; align-items: flex-start; gap: 10px;\n    padding-right: 42px;\n  }\n  #psvk-app .psvk-promobar-badge { font-size: 16px; padding: 8px 11px 6px; }\n  #psvk-app .psvk-promobar-text { font-size: 13.5px; max-width: 34ch; }\n  #psvk-app .psvk-promobar-cta { justify-content: center; width: 100%; padding: 13px 20px; font-size: 16px; }\n  #psvk-app.psvk-has-promobar .psvk-footer { padding-bottom: 170px; }\n}\n\n@media (max-width: 520px) {\n  #psvk-app .psvk-grid-4,\n  #psvk-app .psvk-grid-3,\n  #psvk-app .psvk-grid-2 { grid-template-columns: repeat(2, 1fr); gap: 12px; }\n  #psvk-app .psvk-grid-auto { grid-template-columns: 1fr; }\n\n  #psvk-app .psvk-stats,\n  #psvk-app .psvk-stats-4 { grid-template-columns: 1fr; }\n  #psvk-app .psvk-stats li {\n    flex-direction: row; align-items: baseline; gap: 12px;\n    padding: 14px 0;\n    border-bottom: 1px solid rgba(255, 255, 255, 0.2);\n  }\n  #psvk-app .psvk-stats li:last-child { border-bottom: none; padding-bottom: 26px; }\n  #psvk-app .psvk-stat-num { font-size: 38px; }\n  #psvk-app .psvk-stat-label { font-size: 12px; }\n\n  #psvk-app .psvk-card-title { font-size: 20px; }\n  #psvk-app .psvk-overhang { font-size: 34px; margin-bottom: 8px; }\n  #psvk-app .psvk-tiles { grid-template-columns: repeat(auto-fill, minmax(62px, 1fr)); }\n  #psvk-app .psvk-tile { font-size: 25px; }\n  #psvk-app .psvk-filter { padding: 9px 14px; font-size: 16px; }\n  #psvk-app .psvk-btn { width: 100%; justify-content: center; }\n  #psvk-app .psvk-logo img { height: 38px; }\n}\n";

/** `assets/psv-framework.js`: hoort ongewijzigd in elke pagina. */
export const FRAMEWORK_JS = "/* ============================================================\n   PSV CAMPAIGN KIT — v1.0\n   Basis-JavaScript voor campagnepagina's in Playable.\n\n   Plak dit ONGEWIJZIGD in het JavaScript-veld.\n   Pagina-specifieke code zet je eronder in een eigen IIFE.\n\n   Elk onderdeel start alleen als de bijbehorende markup bestaat,\n   dus je kunt secties weglaten zonder iets aan te passen.\n   ============================================================ */\n\n(function () {\n  'use strict';\n\n  var ROOT_ID = 'psvk-app';\n  var booted = false;\n\n  var reduceMotion = window.matchMedia\n    && window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n\n  /* ---------- Kleine hulpjes ---------- */\n\n  function alle(root, selector) {\n    return Array.prototype.slice.call(root.querySelectorAll(selector));\n  }\n\n  /* Maakt tekst vergelijkbaar: kleine letters, zonder accenten.\n     Zo vindt \"kovar\" ook Kovář. */\n  function normaliseer(tekst) {\n    var t = String(tekst || '').toLowerCase();\n    if (t.normalize) t = t.normalize('NFD').replace(/[\\u0300-\\u036f]/g, '');\n    return t;\n  }\n\n  function headerHoogte(root) {\n    var header = root.querySelector('.psvk-header');\n    return header ? header.offsetHeight : 0;\n  }\n\n  function scrollNaar(root, el, marge) {\n    var top = el.getBoundingClientRect().top + window.pageYOffset\n            - headerHoogte(root) - (marge || 0);\n    window.scrollTo({\n      top: top < 0 ? 0 : top,\n      behavior: reduceMotion ? 'auto' : 'smooth'\n    });\n  }\n\n  /* ---------- Beeld: verberg wat niet laadt ----------\n     Zolang een src een placeholder is of faalt, blijft het\n     rode vlak eronder zichtbaar in plaats van een kapot icoon.\n     Markup: <img data-psvk-photo> */\n\n  function initBeeld(root) {\n    alle(root, '[data-psvk-photo]').forEach(function (img) {\n      function verberg() { img.style.display = 'none'; }\n      img.addEventListener('error', verberg);\n      if (img.complete && img.naturalWidth === 0) verberg();\n    });\n  }\n\n  /* ---------- Ankerlinks binnen de pagina ----------\n     Markup: <a href=\"#sectie-id\" data-psvk-scroll> */\n\n  function initScroll(root) {\n    alle(root, '[data-psvk-scroll]').forEach(function (link) {\n      link.addEventListener('click', function (event) {\n        var id = (link.getAttribute('href') || '').replace('#', '');\n        var doel = id ? root.querySelector('#' + id) : null;\n        if (!doel) return;\n        event.preventDefault();\n        scrollNaar(root, doel, 12);\n      });\n    });\n  }\n\n  /* ---------- Tellers ----------\n     Telt op zodra het cijfer in beeld komt.\n     Markup: <span data-psvk-count=\"28\">28</span> */\n\n  function initTellers(root) {\n    var tellers = alle(root, '[data-psvk-count]');\n    if (!tellers.length) return;\n\n    function tel(el) {\n      var doel = parseInt(el.getAttribute('data-psvk-count'), 10) || 0;\n      if (reduceMotion) { el.textContent = String(doel); return; }\n\n      var start = null;\n      var duur = 1100;\n\n      function stap(nu) {\n        if (start === null) start = nu;\n        var voortgang = Math.min((nu - start) / duur, 1);\n        var eased = 1 - Math.pow(1 - voortgang, 3);\n        el.textContent = String(Math.round(doel * eased));\n        if (voortgang < 1) window.requestAnimationFrame(stap);\n      }\n\n      el.textContent = '0';\n      window.requestAnimationFrame(stap);\n    }\n\n    if ('IntersectionObserver' in window) {\n      var kijker = new IntersectionObserver(function (entries) {\n        entries.forEach(function (entry) {\n          if (!entry.isIntersecting) return;\n          tel(entry.target);\n          kijker.unobserve(entry.target);\n        });\n      }, { threshold: 0.4 });\n      tellers.forEach(function (el) { kijker.observe(el); });\n    } else {\n      tellers.forEach(tel);\n    }\n  }\n\n  /* ---------- Filteren en zoeken ----------\n     Markup:\n       filterknop  <button data-psvk-filter=\"keepers\">\n       vrije vlag  <button data-psvk-filter=\"nieuw\">   (kijkt naar data-psvk-flag)\n       item        <article data-psvk-group=\"keepers\"\n                            data-psvk-flag=\"nieuw\"\n                            data-psvk-search=\"Nick Olij\">\n       zoekveld    <input id=\"psvk-search\">\n       wisknop     <button id=\"psvk-search-clear\">\n       lege staat  <p id=\"psvk-empty\">\n     De waarde \"alles\" toont alles. */\n\n  var filterState = { groep: 'alles', zoek: '' };\n  var filterApi = null;\n\n  function initFilters(root) {\n    var knoppen = alle(root, '[data-psvk-filter]');\n    var items = alle(root, '[data-psvk-group]');\n    if (!knoppen.length && !items.length) return;\n\n    var leeg = root.querySelector('#psvk-empty');\n    var zoekveld = root.querySelector('#psvk-search');\n    var wisknop = root.querySelector('#psvk-search-clear');\n\n    function pasToe() {\n      var zichtbaar = 0;\n\n      items.forEach(function (item) {\n        var groep = item.getAttribute('data-psvk-group');\n        var vlag = item.getAttribute('data-psvk-flag') || '';\n        var naam = normaliseer(item.getAttribute('data-psvk-search') || item.textContent);\n\n        var groepMatch;\n        if (filterState.groep === 'alles') {\n          groepMatch = true;\n        } else if (groep === filterState.groep) {\n          groepMatch = true;\n        } else {\n          groepMatch = (' ' + vlag + ' ').indexOf(' ' + filterState.groep + ' ') !== -1;\n        }\n\n        var zoekMatch = filterState.zoek === '' || naam.indexOf(filterState.zoek) !== -1;\n        var match = groepMatch && zoekMatch;\n\n        item.hidden = !match;\n        if (match) zichtbaar++;\n      });\n\n      knoppen.forEach(function (knop) {\n        var aan = knop.getAttribute('data-psvk-filter') === filterState.groep;\n        knop.classList.toggle('psvk-filter-on', aan);\n        knop.setAttribute('aria-pressed', aan ? 'true' : 'false');\n      });\n\n      if (leeg) {\n        leeg.hidden = zichtbaar > 0;\n        leeg.textContent = filterState.zoek\n          ? 'Niets gevonden voor deze zoekterm.'\n          : 'Niets in deze categorie.';\n      }\n\n      if (wisknop) wisknop.hidden = filterState.zoek === '';\n    }\n\n    knoppen.forEach(function (knop) {\n      knop.setAttribute('aria-pressed', knop.classList.contains('psvk-filter-on') ? 'true' : 'false');\n      knop.addEventListener('click', function () {\n        filterState.groep = knop.getAttribute('data-psvk-filter') || 'alles';\n        pasToe();\n      });\n    });\n\n    if (zoekveld) {\n      zoekveld.addEventListener('input', function () {\n        filterState.zoek = normaliseer(zoekveld.value.trim());\n        pasToe();\n      });\n      zoekveld.addEventListener('keydown', function (event) {\n        if (event.key !== 'Escape') return;\n        zoekveld.value = '';\n        filterState.zoek = '';\n        pasToe();\n      });\n    }\n\n    if (wisknop) {\n      wisknop.addEventListener('click', function () {\n        if (!zoekveld) return;\n        zoekveld.value = '';\n        filterState.zoek = '';\n        pasToe();\n        zoekveld.focus();\n      });\n    }\n\n    filterApi = {\n      reset: function () {\n        if (filterState.groep === 'alles' && filterState.zoek === '') return;\n        filterState.groep = 'alles';\n        filterState.zoek = '';\n        if (zoekveld) zoekveld.value = '';\n        pasToe();\n      }\n    };\n\n    pasToe();\n  }\n\n  /* ---------- Springen van tegel naar item ----------\n     Markup:\n       tegel  <button data-psvk-jump=\"24\">24</button>\n       doel   <article data-psvk-anchor=\"24\">\n     Actieve filters worden losgelaten zodat het doel zeker in beeld staat. */\n\n  function initSprong(root) {\n    var tegels = alle(root, '[data-psvk-jump]');\n    if (!tegels.length) return;\n\n    var timer = null;\n\n    function markeer(doel) {\n      alle(root, '[data-psvk-anchor]').forEach(function (el) {\n        el.classList.remove('psvk-flash');\n      });\n      if (timer) window.clearTimeout(timer);\n\n      void doel.offsetWidth; /* forceert herstart van de animatie */\n      doel.classList.add('psvk-flash');\n\n      timer = window.setTimeout(function () {\n        doel.classList.remove('psvk-flash');\n      }, 3000);\n    }\n\n    tegels.forEach(function (tegel) {\n      tegel.addEventListener('click', function () {\n        var sleutel = tegel.getAttribute('data-psvk-jump');\n        var doel = root.querySelector('[data-psvk-anchor=\"' + sleutel + '\"]');\n        if (!doel) return;\n\n        tegels.forEach(function (andere) {\n          andere.classList.toggle('psvk-tile-on', andere === tegel);\n        });\n\n        if (filterApi) filterApi.reset();\n\n        scrollNaar(root, doel, 24);\n        markeer(doel);\n      });\n    });\n  }\n\n  /* ---------- Uitklappers ----------\n     Markup:\n       <div class=\"psvk-accordion-item\">\n         <button class=\"psvk-accordion-head\" data-psvk-accordion aria-expanded=\"false\">…</button>\n         <div class=\"psvk-accordion-body\" hidden>…</div>\n       </div> */\n\n  function initAccordion(root) {\n    alle(root, '[data-psvk-accordion]').forEach(function (kop) {\n      kop.addEventListener('click', function () {\n        var item = kop.closest('.psvk-accordion-item');\n        if (!item) return;\n        var body = item.querySelector('.psvk-accordion-body');\n        var open = kop.getAttribute('aria-expanded') === 'true';\n\n        kop.setAttribute('aria-expanded', open ? 'false' : 'true');\n        if (body) body.hidden = open;\n      });\n    });\n  }\n\n  /* ---------- Sticky actiebalk ----------\n     Markup: zie de starter-HTML.\n     Wegklikken onthouden we per tabsessie. Vervang sessionStorage\n     door localStorage als de balk permanent weg moet blijven. */\n\n  function initPromobar(root) {\n    var balk = root.querySelector('#psvk-promobar');\n    if (!balk) return;\n\n    var sluit = root.querySelector('#psvk-promobar-close');\n    var SLEUTEL = 'psvk-promobar-weg';\n\n    var alWeg = false;\n    try { alWeg = window.sessionStorage.getItem(SLEUTEL) === '1'; } catch (e) {}\n\n    if (alWeg) {\n      if (balk.parentNode) balk.parentNode.removeChild(balk);\n      return;\n    }\n\n    root.classList.add('psvk-has-promobar');\n    window.setTimeout(function () { balk.classList.add('psvk-promobar-in'); }, 400);\n\n    if (!sluit) return;\n    sluit.addEventListener('click', function () {\n      balk.classList.remove('psvk-promobar-in');\n      root.classList.remove('psvk-has-promobar');\n      try { window.sessionStorage.setItem(SLEUTEL, '1'); } catch (e) {}\n      window.setTimeout(function () { balk.style.display = 'none'; }, 320);\n    });\n  }\n\n  /* ---------- Start ---------- */\n\n  function boot(root) {\n    if (booted) return;\n    booted = true;\n\n    initBeeld(root);\n    initScroll(root);\n    initTellers(root);\n    initFilters(root);\n    initSprong(root);\n    initAccordion(root);\n    initPromobar(root);\n\n    /* Haak voor pagina-specifieke code:\n       window.addEventListener('psvk:ready', function (e) { e.detail.root … }); */\n    try {\n      root.dispatchEvent(new CustomEvent('psvk:ready', {\n        bubbles: true,\n        detail: { root: root, scrollNaar: scrollNaar, normaliseer: normaliseer }\n      }));\n    } catch (e) {}\n  }\n\n  /* Playable rendert het blok soms pas later, of bouwt de DOM opnieuw op.\n     Vandaar de observer met een interval als vangnet. */\n  function probeer() {\n    var root = document.getElementById(ROOT_ID);\n    if (!root) return false;\n    boot(root);\n    return true;\n  }\n\n  if (probeer()) return;\n\n  var observer = new MutationObserver(function () {\n    if (probeer()) observer.disconnect();\n  });\n  observer.observe(document.documentElement, { childList: true, subtree: true });\n\n  var pogingen = 0;\n  var timer = setInterval(function () {\n    pogingen++;\n    if (probeer() || pogingen > 40) clearInterval(timer);\n  }, 250);\n})();\n";

/** `assets/psv-page-starter.html`: het skelet met alle sectietypes. */
export const STARTER_HTML = "<!-- ============================================================\n     PSV CAMPAIGN KIT — startpagina\n     Kopieer dit in het HTML-blok en gooi weg wat je niet gebruikt.\n\n     Elke sectie hieronder is losstaand. De volgorde is vrij.\n     Vervang PLACEHOLDER-teksten en href=\"#\" door je eigen content.\n     ============================================================ -->\n\n<div id=\"psvk-app\" class=\"psvk-app\">\n\n  <a class=\"psvk-skiplink\" href=\"#psvk-main\">Ga naar de inhoud</a>\n\n  <!-- ========== HEADER (rode balk, logo gecentreerd) ========== -->\n  <header class=\"psvk-header\">\n    <div class=\"psvk-wrap psvk-header-inner\">\n      <a class=\"psvk-logo\" href=\"https://www.psv.nl\" target=\"_blank\" rel=\"noopener\">\n        <img src=\"/files/4075/uploads/16747a71-3f29-4df4-9e77-9590a956f8ec.png\" alt=\"PSV\" fetchpriority=\"high\">\n      </a>\n    </div>\n  </header>\n\n  <main id=\"psvk-main\">\n\n  <!-- ========== HERO ==========\n       Varianten: psvk-red (beeld op rood) of psvk-dark (beeld op zwart). -->\n  <section class=\"psvk-hero psvk-red\">\n    <div class=\"psvk-hero-inner\">\n      <h1 class=\"psvk-hero-title\">\n        <span style=\"display:block\">Eerste regel</span>\n        <span class=\"psvk-mark\">Uitgelicht</span>\n      </h1>\n      <p class=\"psvk-hero-lead\">Eén of twee zinnen die vertellen wat er op deze pagina te halen valt.</p>\n      <div class=\"psvk-hero-cta\">\n        <a class=\"psvk-btn psvk-btn-primary\" href=\"#psvk-blok-1\" data-psvk-scroll>Hoofdactie</a>\n        <a class=\"psvk-btn psvk-btn-outline\" href=\"https://www.psvfanstore.nl\" target=\"_blank\" rel=\"noopener\">Tweede actie</a>\n      </div>\n    </div>\n\n    <!-- Cijferbalk, mag weg. Voeg psvk-stats-4 toe voor vier kolommen. -->\n    <ul class=\"psvk-stats\">\n      <li><span class=\"psvk-stat-num\" data-psvk-count=\"28\">28</span><span class=\"psvk-stat-label\">label</span></li>\n      <li><span class=\"psvk-stat-num\" data-psvk-count=\"8\">8</span><span class=\"psvk-stat-label\">label</span></li>\n      <li><span class=\"psvk-stat-num\" data-psvk-count=\"13\">13</span><span class=\"psvk-stat-label\">label</span></li>\n    </ul>\n  </section>\n\n  <!-- ========== TEKST MET BEELD (licht) ========== -->\n  <section class=\"psvk-section psvk-light\" id=\"psvk-blok-1\">\n    <div class=\"psvk-wrap\">\n      <header class=\"psvk-head\">\n        <h2 class=\"psvk-title\">Kop van deze sectie</h2>\n        <p class=\"psvk-lead\">Korte introductie van maximaal twee zinnen.</p>\n      </header>\n\n      <div class=\"psvk-split psvk-split-wide\">\n        <div class=\"psvk-prose\">\n          <p>Eerste alinea met de kern van het verhaal.</p>\n          <p>Tweede alinea met de details.</p>\n          <a class=\"psvk-link\" href=\"#\" style=\"margin-top:16px\">Lees meer</a>\n        </div>\n        <div class=\"psvk-card-media psvk-card-media-wide\">\n          <img src=\"PLACEHOLDER.jpg\" alt=\"\" data-psvk-photo loading=\"lazy\" decoding=\"async\">\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ========== KAARTENRASTER (licht) ==========\n       psvk-grid-2 / -3 / -4 / -auto -->\n  <section class=\"psvk-section psvk-light\">\n    <div class=\"psvk-wrap\">\n      <header class=\"psvk-head\">\n        <h2 class=\"psvk-title\">Raster met kaarten</h2>\n        <p class=\"psvk-lead\">Bijvoorbeeld nieuws, producten, spelers of programmaonderdelen.</p>\n      </header>\n\n      <div class=\"psvk-grid psvk-grid-4\">\n\n        <article class=\"psvk-card psvk-card-hover\" style=\"display:flex;flex-direction:column\">\n          <div class=\"psvk-card-media psvk-card-media-square\">\n            <img src=\"PLACEHOLDER.jpg\" alt=\"\" data-psvk-photo loading=\"lazy\" decoding=\"async\">\n            <span class=\"psvk-badge\">Label</span>\n            <span class=\"psvk-strip\">Onderschrift</span>\n          </div>\n          <div class=\"psvk-card-body\">\n            <h3 class=\"psvk-card-title\">Titel</h3>\n            <p class=\"psvk-card-text\">Eén zin toelichting.</p>\n            <a class=\"psvk-link psvk-link-footer\" href=\"#\">Lees meer</a>\n          </div>\n        </article>\n\n        <!-- kopieer bovenstaande <article> voor de volgende kaart -->\n\n      </div>\n    </div>\n  </section>\n\n  <!-- ========== TEGELS (donker) ==========\n       data-psvk-jump verwijst naar een data-psvk-anchor verderop.\n       Laat data-psvk-jump weg als de tegels alleen ter illustratie zijn. -->\n  <section class=\"psvk-section psvk-dark\" id=\"psvk-blok-2\">\n    <div class=\"psvk-wrap\">\n      <header class=\"psvk-head\">\n        <h2 class=\"psvk-title\">Raster met tegels</h2>\n        <p class=\"psvk-lead\">Tik op een tegel en je springt naar het bijbehorende item.</p>\n      </header>\n\n      <ul class=\"psvk-tiles\">\n        <li><button type=\"button\" class=\"psvk-tile\" data-psvk-jump=\"1\">1</button></li>\n        <li><button type=\"button\" class=\"psvk-tile psvk-tile-accent\" data-psvk-jump=\"2\">2</button></li>\n        <li><button type=\"button\" class=\"psvk-tile\" data-psvk-jump=\"3\">3</button></li>\n      </ul>\n\n      <p class=\"psvk-legend\"><span class=\"psvk-legend-dot\"></span> Betekenis van de rode tegels</p>\n    </div>\n  </section>\n\n  <!-- ========== FILTERBAAR OVERZICHT (licht) ==========\n       data-psvk-group = categorie, data-psvk-flag = extra vlag,\n       data-psvk-search = waarop gezocht wordt,\n       data-psvk-anchor = doel van een tegel hierboven. -->\n  <section class=\"psvk-section psvk-light\" id=\"psvk-blok-3\">\n    <div class=\"psvk-wrap\">\n      <header class=\"psvk-head\">\n        <h2 class=\"psvk-title\">Overzicht met filters</h2>\n        <p class=\"psvk-lead\">Filter op categorie of zoek direct op naam.</p>\n      </header>\n\n      <div class=\"psvk-toolbar\">\n        <div class=\"psvk-filters\" role=\"group\" aria-label=\"Filter\">\n          <button type=\"button\" class=\"psvk-filter psvk-filter-on\" data-psvk-filter=\"alles\">Alles <span>3</span></button>\n          <button type=\"button\" class=\"psvk-filter\" data-psvk-filter=\"groep-a\">Groep A <span>2</span></button>\n          <button type=\"button\" class=\"psvk-filter\" data-psvk-filter=\"groep-b\">Groep B <span>1</span></button>\n          <button type=\"button\" class=\"psvk-filter psvk-filter-accent\" data-psvk-filter=\"nieuw\">Nieuw <span>1</span></button>\n        </div>\n\n        <div class=\"psvk-search\">\n          <label class=\"psvk-visually-hidden\" for=\"psvk-search\">Zoeken</label>\n          <input type=\"text\" id=\"psvk-search\" placeholder=\"Zoeken\" autocomplete=\"off\" spellcheck=\"false\">\n          <button type=\"button\" class=\"psvk-search-clear\" id=\"psvk-search-clear\" aria-label=\"Wis het zoekveld\" hidden>\n            <span aria-hidden=\"true\">&times;</span>\n          </button>\n        </div>\n      </div>\n\n      <div class=\"psvk-grid psvk-grid-4\">\n\n        <article class=\"psvk-card psvk-card-hover\"\n                 data-psvk-group=\"groep-a\"\n                 data-psvk-anchor=\"1\"\n                 data-psvk-search=\"Naam van het item\">\n          <div class=\"psvk-card-media\">\n            <img src=\"PLACEHOLDER.jpg\" alt=\"\" data-psvk-photo loading=\"lazy\" decoding=\"async\">\n          </div>\n          <div class=\"psvk-card-body\">\n            <span class=\"psvk-overhang\">1</span>\n            <h3 class=\"psvk-card-title\">Naam</h3>\n            <p class=\"psvk-card-meta\">Categorie</p>\n          </div>\n        </article>\n\n        <article class=\"psvk-card psvk-card-hover\"\n                 data-psvk-group=\"groep-a\"\n                 data-psvk-flag=\"nieuw\"\n                 data-psvk-anchor=\"2\"\n                 data-psvk-search=\"Tweede item\">\n          <div class=\"psvk-card-media\">\n            <img src=\"PLACEHOLDER.jpg\" alt=\"\" data-psvk-photo loading=\"lazy\" decoding=\"async\">\n            <span class=\"psvk-badge\">Nieuw</span>\n          </div>\n          <div class=\"psvk-card-body\">\n            <span class=\"psvk-overhang\">2</span>\n            <h3 class=\"psvk-card-title\">Naam</h3>\n            <p class=\"psvk-card-meta\">Categorie</p>\n          </div>\n        </article>\n\n        <article class=\"psvk-card psvk-card-hover\"\n                 data-psvk-group=\"groep-b\"\n                 data-psvk-anchor=\"3\"\n                 data-psvk-search=\"Derde item\">\n          <div class=\"psvk-card-media\">\n            <img src=\"PLACEHOLDER.jpg\" alt=\"\" data-psvk-photo loading=\"lazy\" decoding=\"async\">\n          </div>\n          <div class=\"psvk-card-body\">\n            <span class=\"psvk-overhang\">3</span>\n            <h3 class=\"psvk-card-title\">Naam</h3>\n            <p class=\"psvk-card-meta\">Categorie</p>\n          </div>\n        </article>\n\n      </div>\n\n      <p class=\"psvk-empty\" id=\"psvk-empty\" hidden>Niets gevonden.</p>\n    </div>\n  </section>\n\n  <!-- ========== RIJENLIJST (grijs) ========== -->\n  <section class=\"psvk-section psvk-grey\">\n    <div class=\"psvk-wrap\">\n      <header class=\"psvk-head\">\n        <h2 class=\"psvk-title\">Lijst met feiten</h2>\n      </header>\n\n      <ul class=\"psvk-rows\">\n        <li><span class=\"psvk-row-label\">Label</span><span class=\"psvk-row-value\">Waarde</span></li>\n        <li><span class=\"psvk-row-label\">Label</span><span class=\"psvk-row-value\">Waarde</span></li>\n        <li><span class=\"psvk-row-label\">Label</span><span class=\"psvk-row-value\">Waarde</span></li>\n      </ul>\n    </div>\n  </section>\n\n  <!-- ========== UITKLAPPERS (licht) ========== -->\n  <section class=\"psvk-section psvk-light\">\n    <div class=\"psvk-wrap psvk-wrap-narrow\">\n      <header class=\"psvk-head\">\n        <h2 class=\"psvk-title\">Veelgestelde vragen</h2>\n      </header>\n\n      <div class=\"psvk-accordion\">\n        <div class=\"psvk-accordion-item\">\n          <button type=\"button\" class=\"psvk-accordion-head\" data-psvk-accordion aria-expanded=\"false\">\n            Vraag één\n            <span class=\"psvk-accordion-icon\" aria-hidden=\"true\"></span>\n          </button>\n          <div class=\"psvk-accordion-body\" hidden>\n            <p>Antwoord op de vraag.</p>\n          </div>\n        </div>\n\n        <div class=\"psvk-accordion-item\">\n          <button type=\"button\" class=\"psvk-accordion-head\" data-psvk-accordion aria-expanded=\"false\">\n            Vraag twee\n            <span class=\"psvk-accordion-icon\" aria-hidden=\"true\"></span>\n          </button>\n          <div class=\"psvk-accordion-body\" hidden>\n            <p>Antwoord op de vraag.</p>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ========== AFSLUITENDE ACTIE (donker) ========== -->\n  <section class=\"psvk-section psvk-dark\">\n    <div class=\"psvk-wrap\">\n      <h2 class=\"psvk-title\">Kop die tot actie aanzet</h2>\n      <p class=\"psvk-lead\" style=\"margin-bottom:28px\">Eén zin die uitlegt wat de bezoeker hierna kan doen.</p>\n      <a class=\"psvk-btn psvk-btn-primary\" href=\"https://www.psvfanstore.nl\" target=\"_blank\" rel=\"noopener\">Actie</a>\n    </div>\n  </section>\n\n  </main>\n\n  <!-- ========== FOOTER ========== -->\n  <footer class=\"psvk-footer\">\n    <div class=\"psvk-wrap\">\n      <p class=\"psvk-footer-note\">PSV | 2026</p>\n    </div>\n  </footer>\n\n  <!-- ========== STICKY ACTIEBALK (optioneel) ========== -->\n  <div class=\"psvk-promobar\" id=\"psvk-promobar\" role=\"region\" aria-label=\"Actie\">\n    <div class=\"psvk-wrap psvk-promobar-inner\">\n\n      <div class=\"psvk-promobar-copy\">\n        <span class=\"psvk-promobar-badge\">Label</span>\n        <p class=\"psvk-promobar-text\">Eén zin over de actie.</p>\n      </div>\n\n      <a class=\"psvk-promobar-cta\" href=\"https://www.psvfanstore.nl\" target=\"_blank\" rel=\"noopener\">\n        Naar de FANstore\n      </a>\n\n      <button type=\"button\" class=\"psvk-promobar-close\" id=\"psvk-promobar-close\" aria-label=\"Sluit deze melding\">\n        <span aria-hidden=\"true\">&times;</span>\n      </button>\n\n    </div>\n  </div>\n\n</div>\n";
